import React from "react";
import "./Footer.css";

const footerLinks = [
  { label: "Email",    href: "mailto:hello@arshanaslam.me" },
  { label: "GitHub",   href: "https://github.com/arshanaslam1", external: true },
  { label: "LinkedIn", href: "https://linkedin.com/in/arshanaslam1", external: true },
  { label: "Blog",     href: "https://blog.arshanaslam.me", external: true },
];

export default function Footer() {
  const scrollTop = (e) => {
    e.preventDefault();
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  return (
    <footer className="footer">
      <div className="footer-inner">
        <span className="footer-copy">
          © 2026 Arshan Aslam. Built with intention.
        </span>
        <div className="footer-links">
          <a href="#top" className="footer-link" onClick={scrollTop}>
            Back to top ↑
          </a>
          {footerLinks.map((link) => (
            <a
              key={link.label}
              href={link.href}
              className="footer-link"
              target={link.external ? "_blank" : undefined}
              rel={link.external ? "noopener noreferrer" : undefined}
            >
              {link.label}
            </a>
          ))}
        </div>
      </div>
    </footer>
  );
}
